import React, { useState, useRef } from 'react';
import Img1 from "../image.png";

import {
  CheckIcon,
  ArrowRightIcon,
  SparklesIcon,
  RocketLaunchIcon,
  BuildingOffice2Icon,
  XMarkIcon,
  PlusIcon,
} from '@heroicons/react/24/outline';

const plans = [
  {
    id: '01',
    name: 'Starter',
    tagline: 'Small Clinics & Startups',
    icon: RocketLaunchIcon,
    headerGradient: 'from-blue-600 to-blue-500',
    accentColor: 'text-blue-600',
    monthlyPrice: 20000,
    items: [
      { name: 'SEO (On-page, Off-page, Local SEO)', desc: 'Basic' },
      { name: 'Google Ads (Search, Display, Local)', desc: '1 Campaign' },
      { name: 'Meta Ads (Facebook & Instagram)', desc: '1 Campaign' },
      { name: 'Social Media Management', desc: '4 Posts / Month' },
      { name: 'Creative Designs (Images, Banners, Videos)', desc: '8 Creatives / Month' },
      { name: 'AI Reels & Short Videos', desc: '2 AI Reels / Month' },
      { name: 'Blogs / Content Writing', desc: '2 / Month' },
      { name: 'Lead Generation', desc: 'Basic' },
      { name: 'Website / Landing Page', desc: 'Basic' },
      { name: 'Analytics & Reporting', desc: 'Monthly' },
      { name: 'Strategy Meetings', desc: '1 / Month' },
      { name: 'Support', desc: 'Standard' },
    ],
  },
  {
    id: '02',
    name: 'Growth',
    tagline: 'Growing Healthcare Businesses',
    icon: SparklesIcon,
    headerGradient: 'from-emerald-600 to-green-500',
    accentColor: 'text-emerald-600',
    monthlyPrice: 25000,
    items: [
      { name: 'SEO (On-page, Off-page, Local SEO)', desc: 'Advanced' },
      { name: 'Google Ads (Search, Display, Local)', desc: '2 - 3 Campaigns' },
      { name: 'Meta Ads (Facebook & Instagram)', desc: '2 - 3 Campaigns' },
      { name: 'Social Media Management', desc: '8 Posts / Month' },
      { name: 'Creative Designs (Images, Banners, Videos)', desc: '15 - 20 Creatives / Month' },
      { name: 'AI Reels & Short Videos', desc: '4 - 6 AI Reels / Month' },
      { name: 'Blogs / Content Writing', desc: '4 / Month' },
      { name: 'Lead Generation', desc: 'Standard' },
      { name: 'Website / Landing Page', desc: 'Optimized' },
      { name: 'Analytics & Reporting', desc: 'Performance Reports' },
      { name: 'Strategy Meetings', desc: '2 / Month' },
      { name: 'Support', desc: 'Priority' },
    ],
  },
  {
    id: '03',
    name: 'Transform',
    tagline: 'Hospitals & Established Brands',
    icon: BuildingOffice2Icon,
    headerGradient: 'from-purple-700 to-indigo-800',
    accentColor: 'text-purple-600',
    monthlyPrice: 30000,
    items: [
      { name: 'SEO (On-page, Off-page, Local SEO)', desc: 'Advanced + Technical' },
      { name: 'Google Ads (Search, Display, Local)', desc: '4 - 6 Campaigns' },
      { name: 'Meta Ads (Facebook & Instagram)', desc: '4 - 6 Campaigns + Retargeting' },
      { name: 'Social Media Management', desc: '12 - 16 Posts / Month' },
      { name: 'Creative Designs (Images, Banners, Videos)', desc: '25 - 30 Creatives / Month' },
      { name: 'AI Reels & Short Videos', desc: '8 - 12 AI Reels / Month' },
      { name: 'Blogs / Content Writing', desc: '6 - 8 / Month' },
      { name: 'Lead Generation', desc: 'Advanced' },
      { name: 'Website / Landing Page', desc: 'Advanced + CRO' },
      { name: 'Analytics & Reporting', desc: 'Advanced + ROI Reports' },
      { name: 'Strategy Meetings', desc: '2 - 4 / Month' },
      { name: 'Support', desc: 'Dedicated Account Manager' },
    ],
  },
];

// Add-on services now include a monthlyPrice so each one can show its own price box
const addOnServices = [
  { id: '01', name: 'Landing Page', desc: 'High-converting single-page site', monthlyPrice: 15000 },
  { id: '02', name: 'Business Website', desc: 'Professional multi-page presence', monthlyPrice: 25000 },
  { id: '03', name: 'Professional Website', desc: 'Custom design with advanced features', monthlyPrice: 45000 },
  { id: '04', name: 'E-commerce Website', desc: 'Full online store with payments', monthlyPrice: 60000 },
  { id: '05', name: 'Custom Web Application', desc: 'Tailored web software solutions', monthlyPrice: 80000 },
  { id: '06', name: 'Mobile Application', desc: 'iOS & Android app development', monthlyPrice: 90000 },
  { id: '07', name: 'Web + Mobile Application', desc: 'Complete cross-platform suite', monthlyPrice: 150000 },
  { id: '08', name: 'SEO Setup', desc: 'Foundation technical SEO package', monthlyPrice: 12000 },
  { id: '09', name: 'Branding Package', desc: 'Logo, identity & brand guidelines', monthlyPrice: 20000 },
];

const billingCycles = [
  { key: 'quarterly', label: 'Quarterly', months: 3, discount: 0, periodLabel: 'Quarterly · 90 days' },
  { key: 'halfYearly', label: 'Half-Yearly', months: 6, discount: 0.10, periodLabel: 'Half-Yearly · 180 days' },
  { key: 'yearly', label: 'Yearly', months: 12, discount: 0.25, periodLabel: 'Yearly · 365 days' },
];

export default function Plans() {
  const [selectedPlan, setSelectedPlan] = useState(plans[0]);
  const [billingCycle, setBillingCycle] = useState(billingCycles[0]);
  const [isPriceModalOpen, setIsPriceModalOpen] = useState(false);

  // Separate billing cycle state for the add-on section
  const [addOnBillingCycle, setAddOnBillingCycle] = useState(billingCycles[0]);

  const addOnRef = useRef(null);

  // Calculate pricing based on selected plan and billing cycle (No GST)
  const calculatePrice = () => {
    const monthly = selectedPlan.monthlyPrice;
    const months = billingCycle.months;
    const discount = billingCycle.discount;

    const baseTotal = monthly * months;
    const discountAmount = baseTotal * discount;
    const finalTotal = baseTotal - discountAmount;
    const perMonth = finalTotal / months;

    return {
      perMonth: Math.round(perMonth),
      total: Math.round(finalTotal),
    };
  };

  const pricing = calculatePrice();

  // Calculate a specific add-on's price based on the add-on billing cycle
  const calculateAddOnPrice = (monthlyPrice) => {
    const months = addOnBillingCycle.months;
    const discount = addOnBillingCycle.discount;

    const baseTotal = monthlyPrice * months;
    const discountAmount = baseTotal * discount;
    const finalTotal = baseTotal - discountAmount;
    const perMonth = finalTotal / months;

    return {
      perMonth: Math.round(perMonth),
      total: Math.round(finalTotal),
    };
  };

  const scrollToAddOns = () => {
    addOnRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  return (
    <section id="plans" className="py-4 sm:py-6 bg-gradient-to-b from-white via-slate-50/60 to-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Top Header */}
        <div className="flex flex-col lg:flex-row lg:items-end lg:justify-between gap-6 mb-8 sm:mb-10">
          <div>
            <div className="flex items-center gap-2 mb-3">
              <span className="text-secondary font-bold text-sm tracking-wider">
                — 10
              </span>
              <span className="text-xs font-bold uppercase tracking-widest text-primary">
                OUR PLANS
              </span>
            </div>
            <h2 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold text-gray-900 tracking-tight leading-tight max-w-2xl">
              Digital Growth Packages
            </h2>
            <p className="text-sm text-gray-500 mt-2 font-medium">
              Grow Your Healthcare Practice with Strategic Digital Marketing
            </p>
          </div>

          <p className="text-sm sm:text-base text-gray-600 max-w-lg leading-relaxed">
            Transparent pricing with no hidden fees. Choose the package that fits your practice's stage, or combine services for a custom solution.
          </p>
        </div>

        {/* View Prices Button */}
        <div className="flex justify-center sm:justify-start mb-6">
          <button
            onClick={() => setIsPriceModalOpen(true)}
            className="flex items-center gap-2 bg-primary hover:bg-primary/90 text-white font-semibold text-sm px-5 py-2.5 rounded-xl shadow-md hover:shadow-lg transition-all duration-200 cursor-pointer"
          >
            <img src={Img1} alt="View Prices" className="w-4 h-4 object-contain" />
            <span>View Prices</span>
          </button>
        </div>

        {/* Plan Selector Tabs + ADD-ON Button */}
        <div className="flex flex-wrap items-center gap-3 mb-8">
          {plans.map((plan) => {
            const Icon = plan.icon;
            const isActive = selectedPlan.id === plan.id;
            return (
              <button
                key={plan.id}
                onClick={() => setSelectedPlan(plan)}
                className={`flex items-center gap-2.5 px-5 py-3 rounded-xl font-semibold text-sm transition-all duration-200 cursor-pointer border-2 ${
                  isActive
                    ? 'bg-gray-900 text-white border-gray-900 shadow-lg'
                    : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                }`}
              >
                <Icon className={`w-5 h-5 ${isActive ? 'text-white' : plan.accentColor}`} />
                <span>{plan.name}</span>
                <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
                  isActive ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-500'
                }`}>
                  ₹{plan.monthlyPrice.toLocaleString('en-IN')}/mo
                </span>
              </button>
            );
          })}

          {/* ADD-ON Button */}
          <button
            onClick={scrollToAddOns}
            className="flex items-center gap-2.5 px-5 py-3 rounded-xl font-semibold text-sm transition-all duration-200 cursor-pointer border-2 bg-gradient-to-r from-amber-500 to-orange-500 text-white border-transparent shadow-md hover:shadow-lg hover:from-amber-600 hover:to-orange-600"
          >
            <PlusIcon className="w-5 h-5 text-white" />
            <span>ADD-ON</span>
          </button>
        </div>

        {/* Two Column Layout: Plan Details (Left) + Pricing Card (Right) */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">

          {/* Left Column — Plan Details */}
          <div className="lg:col-span-2 space-y-6">
            {/* Plan Header Card */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 sm:p-8">
              <div className="flex items-start gap-4">
                <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${selectedPlan.headerGradient} flex items-center justify-center flex-shrink-0 shadow-md`}>
                  <selectedPlan.icon className="w-7 h-7 text-white" />
                </div>
                <div>
                  <h3 className="text-2xl font-extrabold text-gray-900 tracking-tight">
                    {selectedPlan.name}
                  </h3>
                  <p className="text-sm text-gray-500 mt-1 font-medium">
                    {selectedPlan.tagline}
                  </p>
                </div>
              </div>
            </div>

            {/* Plan Features */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 sm:p-8">
              <h4 className="text-lg font-bold text-gray-900 mb-1">
                Everything in the {selectedPlan.name} plan
              </h4>
              <p className="text-sm text-gray-500 mb-6">
                Comprehensive digital marketing suite for your practice
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-4">
                {selectedPlan.items.map((item, idx) => (
                  <div key={idx} className="flex items-start gap-3">
                    <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                      <CheckIcon className="w-3 h-3 text-primary" />
                    </div>
                    <div>
                      <h5 className="text-sm font-semibold text-gray-900 leading-tight">
                        {item.name}
                      </h5>
                      <p className="text-xs text-gray-500 mt-0.5">
                        {item.desc}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Add-on Services — now with price boxes + billing toggle + CTA */}
            <div ref={addOnRef} className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 sm:p-8">
              <div className="flex items-center gap-2 mb-1">
                <span className="text-[11px] font-bold uppercase tracking-widest text-primary">
                  ADD-ON SERVICES
                </span>
              </div>
              <h4 className="text-lg font-bold text-gray-900 tracking-tight">
                Development & Setup Services
              </h4>
              <p className="text-xs text-gray-500 mt-1 mb-5">
                One-time builds, priced separately from monthly plans.
              </p>

              {/* Add-on Billing Cycle Toggle */}
              <div className="p-2 bg-slate-100 rounded-xl mb-5">
                <div className="flex gap-1">
                  {billingCycles.map((cycle) => {
                    const isActive = addOnBillingCycle.key === cycle.key;
                    return (
                      <button
                        key={cycle.key}
                        onClick={() => setAddOnBillingCycle(cycle)}
                        className={`flex-1 py-2.5 px-2 rounded-lg text-xs font-bold transition-all duration-200 cursor-pointer ${
                          isActive
                            ? 'bg-primary text-white shadow-md'
                            : 'text-gray-500 hover:text-gray-700 hover:bg-white/60'
                        }`}
                      >
                        {cycle.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Period Label */}
              <p className="text-sm font-semibold text-gray-500 mb-4">
                {addOnBillingCycle.periodLabel}
              </p>

              {/* Add-on Cards Grid — each with its own price box */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {addOnServices.map((addon) => {
                  const addonPricing = calculateAddOnPrice(addon.monthlyPrice);
                  return (
                    <div
                      key={addon.id}
                      className="flex flex-col rounded-2xl border border-gray-100 bg-slate-50 hover:bg-white hover:shadow-md transition-all duration-200 overflow-hidden"
                    >
                      {/* Card Header */}
                      <div className="flex items-start gap-3 px-4 pt-4">
                        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-600 to-emerald-600 flex items-center justify-center flex-shrink-0">
                          <SparklesIcon className="w-4 h-4 text-white" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <h5 className="text-sm font-bold text-gray-900 leading-tight">
                            {addon.name}
                          </h5>
                          <p className="text-[11px] text-gray-500 mt-0.5">
                            {addon.desc}
                          </p>
                        </div>
                      </div>

                      {/* Price Box */}
                      <div className="px-4 pt-3 pb-4 mt-auto">
                        <div className="rounded-xl bg-white border border-gray-100 px-3 py-3">
                          <div className="flex items-baseline gap-1">
                            <span className="text-2xl font-extrabold text-gray-900 tracking-tight">
                              ₹{addonPricing.perMonth.toLocaleString('en-IN')}
                            </span>
                            <span className="text-xs font-semibold text-gray-500">
                              /month
                            </span>
                          </div>
                          <p className="text-[11px] text-gray-500 mt-1">
                            <span className="font-semibold text-gray-700">
                              ₹{addonPricing.total.toLocaleString('en-IN')}
                            </span>{' '}
                            for the plan
                          </p>
                          {addOnBillingCycle.discount > 0 && (
                            <p className="text-[10px] font-bold text-emerald-600 mt-1">
                              Save {Math.round(addOnBillingCycle.discount * 100)}% with {addOnBillingCycle.label.toLowerCase()} billing
                            </p>
                          )}

                          {/* Per-add-on CTA */}
                          <a
                            href="#cta"
                            className="mt-3 flex items-center justify-center gap-2 w-full bg-primary hover:bg-primary/90 text-white font-bold text-xs py-2.5 px-4 rounded-lg shadow-sm hover:shadow-md transition-all duration-200 cursor-pointer"
                          >
                            <span>Book Demo</span>
                            <ArrowRightIcon className="w-3.5 h-3.5" />
                          </a>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Bottom CTA for Add-ons */}
              <div className="mt-6 text-center">
                <p className="text-sm text-gray-600 font-medium mb-3">
                  Not sure which package fits?
                </p>
                <a
                  href="#cta"
                  className="inline-flex items-center gap-2 text-secondary hover:text-secondary/80 font-semibold text-sm transition-colors"
                >
                  <span>Book a free strategy call</span>
                  <ArrowRightIcon className="w-4 h-4" />
                </a>
              </div>
            </div>
          </div>

          {/* Right Column — Sticky Pricing Card */}
          <div className="lg:col-span-1 lg:sticky lg:top-8">
            <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">

              {/* Billing Cycle Toggle */}
              <div className="p-2 bg-slate-100 m-4 rounded-xl">
                <div className="flex gap-1">
                  {billingCycles.map((cycle) => {
                    const isActive = billingCycle.key === cycle.key;
                    return (
                      <button
                        key={cycle.key}
                        onClick={() => setBillingCycle(cycle)}
                        className={`flex-1 py-2.5 px-2 rounded-lg text-xs font-bold transition-all duration-200 cursor-pointer ${
                          isActive
                            ? 'bg-primary text-white shadow-md'
                            : 'text-gray-500 hover:text-gray-700 hover:bg-white/60'
                        }`}
                      >
                        {cycle.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Pricing Display */}
              <div className="px-6 pb-6">
                {/* Period Label */}
                <p className="text-sm font-semibold text-gray-500 mb-3">
                  {billingCycle.periodLabel}
                </p>

                {/* Price */}
                <div className="flex items-baseline gap-1 mb-1">
                  <span className="text-4xl sm:text-5xl font-extrabold text-gray-900 tracking-tight">
                    ₹{pricing.perMonth.toLocaleString('en-IN')}
                  </span>
                  <span className="text-base font-semibold text-gray-500">
                    /month
                  </span>
                </div>

                {/* Total */}
                <div className="space-y-1 mb-5">
                  <p className="text-sm text-gray-500">
                    <span className="font-semibold text-gray-700">
                      ₹{pricing.total.toLocaleString('en-IN')}
                    </span>{' '}
                    for the plan
                  </p>
                  {billingCycle.discount > 0 && (
                    <p className="text-xs font-bold text-emerald-600">
                      You save {Math.round(billingCycle.discount * 100)}% with {billingCycle.label.toLowerCase()} billing
                    </p>
                  )}
                </div>

                {/* CTA Button */}
                <a
                  href="#cta"
                  className="flex items-center justify-center gap-2 w-full bg-primary hover:bg-primary/90 text-white font-bold text-sm py-3.5 px-6 rounded-xl shadow-md hover:shadow-lg transition-all duration-200 cursor-pointer"
                >
                  <span>Book Demo</span>
                  <ArrowRightIcon className="w-4 h-4" />
                </a>
              </div>
            </div>

            {/* Bottom CTA */}
            <div className="mt-6 text-center">
              <p className="text-sm text-gray-600 font-medium mb-3">
                Not sure which package fits?
              </p>
              <a
                href="#cta"
                className="inline-flex items-center gap-2 text-secondary hover:text-secondary/80 font-semibold text-sm transition-colors"
              >
                <span>Book a free strategy call</span>
                <ArrowRightIcon className="w-4 h-4" />
              </a>
            </div>
          </div>
        </div>

      </div>

      {/* PRICE MODAL */}
      {isPriceModalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm transition-opacity duration-300"
          onClick={() => setIsPriceModalOpen(false)}
        >
          <div
            className="relative w-full max-w-3xl max-h-[85vh] bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 bg-white flex-shrink-0">
              <div>
                <h3 className="text-base font-bold text-gray-900">Pricing Details</h3>
                <p className="text-xs text-gray-500 mt-0.5">Digital Growth Packages</p>
              </div>
              <button
                onClick={() => setIsPriceModalOpen(false)}
                className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-colors cursor-pointer"
                aria-label="Close"
              >
                <XMarkIcon className="w-5 h-5" />
              </button>
            </div>

            <div className="flex-1 overflow-auto p-4 sm:p-5 bg-slate-50/50 flex justify-center items-start">
              <img
                src={Img1}
                alt="Pricing Details"
                className="w-full h-auto max-w-full rounded-lg shadow-sm object-contain mx-auto"
              />
            </div>

            <div className="flex items-center justify-end px-5 py-3 border-t border-gray-100 bg-white flex-shrink-0">
              <button
                onClick={() => setIsPriceModalOpen(false)}
                className="px-4 py-2 text-sm font-semibold text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors cursor-pointer"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

    </section>
  );
}
